grant update(title,organization,description,postal_code,address,city,state_code,modality,job_type,required_requirements,desired_requirements,behavioral_profile,benefits,salary) on public.portal_listings to authenticated;
create policy listing_owner_update on public.portal_listings for update to authenticated using(publisher_id=(select auth.uid()) and ((kind='job' and pilot_private.portal_role(cohort_id)='recruiter') or (kind in ('course','training') and pilot_private.portal_role(cohort_id) in ('recruiter','school_staff')))) with check(publisher_id=(select auth.uid()) and ((kind='job' and pilot_private.portal_role(cohort_id)='recruiter') or (kind in ('course','training') and pilot_private.portal_role(cohort_id) in ('recruiter','school_staff'))));